import * as THREE from 'three/webgpu';
import {
  MeshStandardNodeMaterial,
  texture,
  mix,
  vec4,
  vec3,
  color,
  float,
  uv
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  // Root group
  const root = new THREE.Group();
  root.position.set(
    config.position?.[0] ?? 0,
    config.position?.[1] ?? 0,
    config.position?.[2] ?? 0
  );
  root.rotation.set(
    config.rotation?.[0] ?? 0,
    config.rotation?.[1] ?? 0,
    config.rotation?.[2] ?? 0
  );
  root.scale.set(
    config.scale?.[0] ?? 1,
    config.scale?.[1] ?? 1,
    config.scale?.[2] ?? 1
  );

  // Load the base texture (shared among cards)
  const baseTex = ctx.textureLoader('/prism-mock/home/nodes/parallax-stack.png');
  baseTex.flipY = false; // ensure correct orientation for node materials

  // Geometry for cards
  const cardWidth = 1.6;
  const cardHeight = 1.0;
  const planeGeom = new THREE.PlaneGeometry(cardWidth, cardHeight);

  // Bevel geometry (slightly larger)
  const bevelThickness = 0.025;
  const bevelGeom = new THREE.PlaneGeometry(
    cardWidth + bevelThickness * 2,
    cardHeight + bevelThickness * 2
  );

  // Group that holds the whole strip
  const stripGroup = new THREE.Group();
  stripGroup.rotation.y = -THREE.MathUtils.degToRad(18);
  root.add(stripGroup);

  // Store disposables for cleanup
  const disposables = [];

  // Colors
  const inkColor = new THREE.Color('#16161d');
  const accentColor = new THREE.Color('#ff2a38');

  // Create five cards
  const cardCount = 5;
  const pitch = 1.85;
  const focusIndex = Math.floor(cardCount / 2); // 2

  for (let i = 0; i < cardCount; i++) {
    const card = new THREE.Group();

    // Bevel mesh (machined ink frame)
    const bevelMat = new MeshStandardNodeMaterial({
      color: color(inkColor),
      roughness: float(0.7),
      metalness: float(0.0)
    });
    const bevelMesh = new THREE.Mesh(bevelGeom, bevelMat);
    bevelMesh.position.set(0, 0, -0.001); // slightly behind card
    card.add(bevelMesh);
    disposables.push(bevelMat, bevelMesh.geometry);

    // Card material using node texture
    const cardMat = new MeshStandardNodeMaterial({
      map: texture(baseTex),
      roughness: float(0.55),
      metalness: float(0.2),
      clearcoat: float(0.15),
      transparent: true
    });
    const cardMesh = new THREE.Mesh(planeGeom, cardMat);
    card.add(cardMesh);
    disposables.push(cardMat, cardMesh.geometry);

    // Scale & opacity based on distance from focus
    const dist = Math.abs(i - focusIndex);
    const maxDist = focusIndex;
    const scale = i === focusIndex ? 1.0 : 0.92;
    const opacity = i === focusIndex ? 1.0 : 1.0 - 0.45 * (dist / maxDist);
    card.scale.setScalar(scale);
    cardMesh.material.opacity = opacity;
    cardMesh.material.transparent = true;

    // Position along X
    const xPos = (i - focusIndex) * pitch;
    card.position.set(xPos, 0, 0);
    stripGroup.add(card);

    // Underline for focused card
    if (i === focusIndex) {
      const underlineGeom = new THREE.PlaneGeometry(cardWidth, 0.035);
      const underlineMat = new MeshStandardNodeMaterial({
        color: color(accentColor),
        emissive: color(accentColor),
        emissiveIntensity: float(1.3),
        transparent: true,
        opacity: float(1.0)
      });
      const underline = new THREE.Mesh(underlineGeom, underlineMat);
      underline.position.set(0, -cardHeight / 2 - 0.018, 0.001);
      card.add(underline);
      disposables.push(underlineMat, underline.geometry);
    }

    // Caption text (below each card)
    const captions = [
      'NA-01 MERIDIAN',
      'NA-02 NOCTURNE',
      'NA-03 SIGNAL',
      'NA-04 VANTAGE',
      'NA-05 ARCHIVE'
    ];
    const captionText = captions[i];
    const captionObj = ctx.fontAtlas.createText({
      text: captionText,
      fontFamily: 'JetBrains Mono',
      fontWeight: 700,
      fontSize: 0.018, // scene-unit approximation
      color: '#e8ecf2',
      lineHeight: 1.4,
      letterSpacing: 0.08,
      anchor: 'center',
      atlas: 0,
      sourceRect: { x: 0, y: 0, w: 512, h: 320 }
    });
    captionObj.position.set(0, -cardHeight / 2 - 0.07, 0);
    card.add(captionObj);
    disposables.push(captionObj);
  }

  // Headline text
  const headline = ctx.fontAtlas.createText({
    text: 'The collection',
    fontFamily: 'Lora',
    fontWeight: 600,
    fontSize: 0.068,
    color: '#e8ecf2',
    lineHeight: 1.1,
    letterSpacing: -0.005,
    anchor: 'left',
    atlas: 0,
    sourceRect: { x: 0, y: 0, w: 512, h: 320 }
  });
  headline.position.set(-2.6, 1.5, 0);
  root.add(headline);
  disposables.push(headline);

  // Body text
  const body = ctx.fontAtlas.createText({
    text: 'Five calibres. One discipline.',
    fontFamily: 'JetBrains Mono',
    fontWeight: 400,
    fontSize: 0.026,
    color: '#e8ecf2',
    lineHeight: 1.5,
    letterSpacing: 0,
    anchor: 'left',
    atlas: 0,
    sourceRect: { x: 0, y: 0, w: 512, h: 320 }
  });
  body.position.set(-2.6, -1.5, 0);
  root.add(body);
  disposables.push(body);

  // Apply cinematic primitives from config
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[prim.name];
      if (typeof fn === 'function') {
        fn(root, prim.params);
      }
    }
  }

  // Store timelines for cleanup (if any are created later)
  const timelines = [];

  // UserData handlers placeholder
  root.userData.handlers = {};

  // Cleanup method
  root.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const obj of disposables) {
      if (obj && typeof obj.dispose === 'function') {
        obj.dispose();
      }
    }
    // Dispose texture
    if (baseTex && typeof baseTex.dispose === 'function') baseTex.dispose();
  };

  return root;
}
